/**
 * Minimal Express stub for unit-test environments that don't have
 * the real express package installed.  Only surfaces the subset of the
 * Express API that server.js calls at module initialisation time.
 */

function createRouter() {
  const router = {
    use() { return router; },
    get() { return router; },
    post() { return router; },
    listen(port, cb) { if (typeof cb === 'function') cb(); return router; },
  };
  return router;
}

function express() {
  return createRouter();
}

express.json = () => (req, res, next) => { if (next) next(); };
express.static = () => (req, res, next) => { if (next) next(); };
express.Router = createRouter;

export default express;
